+  for (let i = 0; i < sections.length; i++) {
+    if (!Object.prototype.hasOwnProperty.call(sections, i)) {
+      throw new Error(`sections[${i}] is missing (sparse array)`);
+    }
+    const s = sections[i];
+    if (s === null || typeof s !== 'object' || Array.isArray(s)) {
+      throw new Error(`sections[${i}] must be a non-null, non-array object`);
+    }
+    if (typeof s.id !== 'string' || s.id.length === 0) {
+      throw new Error(`sections[${i}].id must be a nonempty string`);
+    }
+    if (typeof s.text !== 'string') {
+      throw new Error(`sections[${i}].text must be a string`);
+    }
+    if (!isNonNegativeSafeInteger(s.priority)) {
+      throw new Error(`sections[${i}].priority must be a nonnegative safe integer`);
+    }
+    if (typeof s.required !== 'boolean') {
+      throw new Error(`sections[${i}].required must be a boolean`);
+    }
+    if (seen.has(s.id)) {
+      throw new Error(`duplicate section id: ${JSON.stringify(s.id)}`);
+    }
+    seen.add(s.id);
+  }
+}
+
+function frameFor(section) {
+  return '### ' + JSON.stringify(section.id) + '\n' + section.text + '\n';
+}
+
+export function packContext(sections, maxBytes) {
+  if (!isNonNegativeSafeInteger(maxBytes)) {
+    throw new Error('maxBytes must be a nonnegative safe integer');
+  }
+  validateSections(sections);
+
+  const indexed = sections.map((s, i) => ({ s, i, frame: frameFor(s) }));
+  const requiredItems = indexed.filter((x) => x.s.required);
+  const optionalItems = indexed.filter((x) => !x.s.required);
+
+  let requiredCost = 0;
+  for (const item of requiredItems) {
+    requiredCost += Buffer.byteLength(item.frame, 'utf8');
+  }
+  if (requiredCost > maxBytes) {
+    throw new Error('required sections exceed maxBytes budget');
+  }
+
+  const sortedOptional = optionalItems.slice().sort((a, b) => {
+    if (b.s.priority !== a.s.priority) return b.s.priority - a.s.priority;
+    return a.i - b.i;
+  });
+
+  let remaining = maxBytes - requiredCost;
+  const includedOptional = [];
+  const omittedOptionalSet = new Set();
+
+  for (const item of sortedOptional) {
+    const cost = Buffer.byteLength(item.frame, 'utf8');
+    if (cost <= remaining) {
+      includedOptional.push(item);
+      remaining -= cost;
+    } else {
+      omittedOptionalSet.add(item.i);
+    }
+  }
+
+  const finalOutput = [];
+  for (const item of requiredItems) finalOutput.push(item);
+  for (const item of includedOptional) finalOutput.push(item);
+
+  const text = finalOutput.map((x) => x.frame).join('');
+  const bytes = Buffer.byteLength(text, 'utf8');
+  const included = finalOutput.map((x) => x.s.id);
+  const omitted = indexed
+    .filter((x) => !x.s.required && omittedOptionalSet.has(x.i))
+    .map((x) => x.s.id);
+
+  return { text, bytes, included, omitted };
+}
+
+function runCli() {
+  const args = process.argv.slice(2);
+  if (args.length !== 1) {
+    process.stderr.write('Usage: node context-packet.js INPUT_JSON_FILE\n');
+    process.exit(2);
+  }
+  let raw;
+  try {
+    raw = readFileSync(args[0], 'utf8');
+  } catch (err) {
+    process.stderr.write(`Failed to read file: ${err.message}\n`);
+    process.exit(2);
+  }
+  let data;
+  try {
+    data = JSON.parse(raw);
+  } catch (err) {
+    process.stderr.write(`Invalid JSON: ${err.message}\n`);
+    process.exit(2);
+  }
+  if (data === null || typeof data !== 'object' || Array.isArray(data)) {
+    process.stderr.write('Input JSON must be an object with sections and maxBytes\n');
+    process.exit(2);
+  }
+  try {
+    const result = packContext(data.sections, data.maxBytes);
+    process.stdout.write(JSON.stringify(result) + '\n');
+  } catch (err) {
+    process.stderr.write(`${err.message}\n`);
+    process.exit(2);
+  }
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
+  runCli();
+}

